sys_variable_value.value:
(function execute(inputs, outputs) {
    
    const api = new x_neyu_google_nyu.DirectoryMemberAPI();

    const extras = {};
    if (!gs.nil(inputs.kind)) {
        extras["kind"] = inputs.kind;
    }
    if (!gs.nil(inputs.type)) {
        extras["type"] = inputs.type;
    }
    if (!gs.nil(inputs.role)) {
        extras["role"] = inputs.role;
    }
    if (!gs.nil(inputs.deliverySettings)) {
        extras["deliverySettings"] = inputs.deliverySettings;
    }

    const response = Object.keys(extras).length != 0 ?
        api.insert(inputs.groupKey, inputs.userKey, extras) :
        api.insert(inputs.groupKey, inputs.userKey);

    if (!response.error && response.status == 200) {
        outputs.error = false;
        outputs.result = JSON.stringify(JSON.parse(response.responseBody));
    } else {
        outputs.error = true;
        outputs.result = !gs.nil(response.errorMessage) ?
            response.errorMessage :
            JSON.stringify(JSON.parse(response.responseBody));
    }

})(inputs, outputs);

